<?php require_once '../config/auth.php';require_role('kepala_sekolah');$pdo=db();$rows=$pdo->query('SELECT k.nama_kelas,j.nama_jurusan,ROUND(AVG(n.nilai_akhir),2) rata, SUM(n.nilai_akhir<75) belum FROM kelas k JOIN jurusan j ON j.id_jurusan=k.id_jurusan JOIN siswa s ON s.id_kelas=k.id_kelas LEFT JOIN nilai n ON n.nis=s.nis GROUP BY k.id_kelas ORDER BY j.nama_jurusan,k.nama_kelas')->fetchAll();$page_title='Rekap Akademik';require '../includes/header.php';require '../includes/sidebar.php'; ?><h2>Rekap Akademik</h2><div class="card p-3"><table class="table"><thead><tr><th>Kelas</th><th>Jurusan</th><th>Rata-rata</th><th>Di bawah KKM</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['nama_kelas']) ?></td><td><?= e($r['nama_jurusan']) ?></td><td><?= e($r['rata']??'-') ?></td><td><?= e($r['belum']??0) ?></td></tr><?php endforeach; ?></tbody></table></div><?php require '../includes/footer.php';
